void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    Set<V> part1 = new HashSet<>();
    Set<V> part2 = new HashSet<>();
    int count = 0;
    for (V vertex : resultMap.values()) {
        if (count < resultMap.size() / 2) {
            part1.add(vertex);
        } else {
            part2.add(vertex);
        }
        count++;
    }
    for (V v1 : part1) {
        for (V v2 : part2) {
            target.addEdge(v1, v2);
        }
    }
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create two disjoint sets of vertices
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    int numVertices = target.getNumVertices();
    int numVerticesSet1 = numVertices / 2;

    for (int i = 0; i < numVerticesSet1; i++) {
        V vertex = target.getVertex(i);
        set1.add(vertex);
    }

    for (int i = numVerticesSet1; i < numVertices; i++) {
        V vertex = target.getVertex(i);
        set2.add(vertex);
    }

    // Add edges between all vertices in set1 and set2
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }

    // Store the partition results in resultMap
    resultMap.put("set1", set1);
    resultMap.put("set2", set2);
}

