protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    while (start < end) {
        long currentEnd = Math.min(start + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(start, currentEnd));
        start = currentEnd;
    }
    return ranges;
}

private static final long FETCH_DATA_DURATION = 3600000; // 1 hour in milliseconds

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentTime = start;

    while (currentTime < end) {
        long remainingTime = end - currentTime;
        long duration = Math.min(remainingTime, FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(currentTime, currentTime + duration));
        currentTime += duration;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    long fetchDataDuration = 60000; // Example value for FETCH_DATA_DURATION in milliseconds

    while (duration > fetchDataDuration) {
        timeRanges.add(new TimeRange(start, start + fetchDataDuration));
        start += fetchDataDuration;
        duration -= fetchDataDuration;
    }

    if (duration > 0) {
        timeRanges.add(new TimeRange(start, end));
    }

    return timeRanges;
}

