static long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket - 1) % dayStep;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    day = (day - 1) / dayStep * dayStep + 1;

    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long datePart = timeBucket / 100L;
    long dayOfMonth = datePart % 100L;
    long adjustedDay = dayOfMonth - dayOfMonth % dayStep;
    return datePart - dayOfMonth + adjustedDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c >= 0 && c <= 127) {
            size += 1;
        } else if (c <= 2047) {
            size += 2;
        } else if (c <= 65535) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

