        if ((c & 0x80) == 0) {
            size += 1;
        } else if ((c & 0xE0) == 0xC0) {
            size += 2;
        } else if ((c & 0xF0) == 0xE0) {
            size += 3;
        } else if ((c & 0xF8) == 0xF0) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character");
        }
    }
    return size;
}

