public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    boolean nextEscape = false;

    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);

        if (nextEscape) {
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new Exception("Illegal escape character: " + ch);
            }
            nextEscape = false;
        } else if (ch == '\\') {
            nextEscape = true;
        } else {
            sb.append(ch);
        }
    }

    return sb.toString();
}

