protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Create a list to store the nodes of the tour
    List<V> nodes = new ArrayList<>();

    // Start with an arbitrary node in the tour
    V currentNode = tour.iterator().next();
    nodes.add(currentNode);

    // Iterate through the tour edges
    for (E edge : tour) {
        // Get the other node of the edge that is not the current node
        Iterator<V> edgeVertices = graph.getEdgeSource(edge).equals(currentNode) 
                                     ? graph.getEdgeTarget(edge).iterator() 
                                     : graph.getEdgeSource(edge).iterator();
        while (edgeVertices.hasNext()) {
            V nextNode = edgeVertices.next();
            if (!nextNode.equals(currentNode)) {
                nodes.add(nextNode);
                currentNode = nextNode;
                break;
            }
        }
    }

    // Create and return the graph path
    return new GraphWalk<>(graph, nodes);
}

